"use client";

import React, { ReactNode, useCallback, useState } from "react";

import Link from "next/link";
import { usePathname } from "next/navigation";

import { Button } from "@/components/ui/button";
import { cn } from "@/registry/utilities/cn";
import { motion, useMotionValueEvent, useScroll } from "motion/react";
import { useTheme } from "next-themes";
import { IoIosClose, IoIosMenu } from "react-icons/io";

import { MouseFollowingEyes } from "./following-eyes";
import { createAnimation } from "./theme-animations";

type Props = {
	navItems: {
		link: string;
		title: string;
		target?: "_blank";
	}[];
};

const DesktopNavbar = ({ navItems }: Props) => {
	const { scrollY } = useScroll();

	const [showFloatingNav, setShowFloatingNav] = useState(false);

	useMotionValueEvent(scrollY, "change", (value) => {
		if (value > 100) {
			setShowFloatingNav(true);
		} else {
			setShowFloatingNav(false);
		}
	});

	const { theme, setTheme } = useTheme();

	const styleId = "theme-transition-styles";

	const updateStyles = React.useCallback((css: string, name: string) => {
		if (typeof window === "undefined") return;

		let styleElement = document.getElementById(styleId) as HTMLStyleElement;

		if (!styleElement) {
			styleElement = document.createElement("style");
			styleElement.id = styleId;
			document.head.appendChild(styleElement);
		}

		styleElement.textContent = css;
	}, []);

	const toggleTheme = React.useCallback(() => {
		const animation = createAnimation(
			"gif",
			"top-left",
			"https://media.giphy.com/media/KBbr4hHl9DSahKvInO/giphy.gif?cid=790b76112m5eeeydoe7et0cr3j3ekb1erunxozyshuhxx2vl&ep=v1_stickers_search&rid=giphy.gif&ct=s"
		);

		updateStyles(animation.css, animation.name);

		if (typeof window === "undefined") return;

		const switchTheme = () => {
			setTheme(theme === "light" ? "dark" : "light");
		};

		if (!document.startViewTransition) {
			switchTheme();
			return;
		}

		document.startViewTransition(switchTheme);
	}, [theme, setTheme]);

	return (
		<div className="w-screen">
			<motion.div
				className={cn(
					"flex relative justify-between px-4 py-3 rounded-md  transition duration-200 bg-transparent mx-auto",
					!showFloatingNav ? "w-screen h-screen" : "w-fit h-fit"
				)}
				animate={{
					width: showFloatingNav ? "80%" : "100vw",
					height: showFloatingNav ? "0%" : "100vh",
					background: showFloatingNav
						? "var(--neutral-900)"
						: "transparent",
				}}
				transition={{
					duration: 0.4,
				}}
				layout
			>
				{navItems.map((item, i) => (
					<motion.div
						className={cn(
							"",
							!showFloatingNav &&
								i === 0 &&
								"top-6 inset-x-0 place-items-center",
							!showFloatingNav &&
								i === 1 &&
								"right-6 inset-y-0 content-center",
							!showFloatingNav &&
								i === 2 &&
								"bottom-6 inset-x-0 place-items-center",
							!showFloatingNav &&
								i === 3 &&
								"left-6 inset-y-0 content-center"
						)}
						animate={{
							position: showFloatingNav ? "relative" : "absolute",
						}}
						transition={{ duration: 0.5 }}
					>
						<NavBarItem
							href={item.link}
							key={item.title}
							target={item.target}
							toggleTheme={toggleTheme}
						>
							{item.title}
						</NavBarItem>
					</motion.div>
				))}
			</motion.div>
			<Link
				href={"/drive25"}
				className="absolute top-1 left-4 w-fit h-fit block z-[500] pointer-events-auto"
			>
				<MouseFollowingEyes />
			</Link>
		</div>
	);
};

const navItems = [
	{
		title: "About Us",
		link: "/drive25/about",
	},
	{
		title: "WATCH REEL",
		link: "/drive25/work",
	},

	{
		title: "CONTACT",
		link: "/drive25/about",
	},
	{
		title: "OUR TEAM",
		link: "/drive25/about",
	},
];

function ResizeNavBar() {
	return (
		<motion.nav
			initial={{
				y: -80,
			}}
			animate={{
				y: 0,
			}}
			transition={{
				ease: [0.6, 0.05, 0.1, 0.9],
				duration: 0.8,
			}}
			className="fixed lg:inset-0 z-[500] pointer-events-none"
		>
			<div className="hidden lg:block">
				<DesktopNavbar navItems={navItems} />
			</div>
			<div className="flex w-full lg:hidden ">
				<MobileNavbar navItems={navItems} />
			</div>
		</motion.nav>
	);
}

const MobileNavbar = ({ navItems }: any) => {
	const [open, setOpen] = useState(false);

	const { scrollY } = useScroll();

	const [showBackground, setShowBackground] = useState(false);

	useMotionValueEvent(scrollY, "change", (value) => {
		if (value > 100) {
			setShowBackground(true);
		} else {
			setShowBackground(false);
		}
	});

	return (
		<div
			className={cn(
				"flex justify-between bg-transparent items-center w-full rounded-md px-2.5 py-1.5 transition duration-200",
				showBackground &&
					" bg-background  shadow-[0px_-2px_0px_0px_var(--neutral-800),0px_2px_0px_0px_var(--neutral-800)]"
			)}
		>
			{/* <Logo /> */}
			<IoIosMenu
				className="text-foreground h-6 w-6"
				onClick={() => setOpen(!open)}
			/>
			{open && (
				<div className="fixed inset-0 bg-background z-50 flex flex-col items-start justify-start space-y-10  pt-5  text-xl text-foreground  transition duration-200 hover:text-foreground">
					<div className="flex items-center justify-between w-full px-5">
						{/* <Logo /> */}
						<div className="flex items-center space-x-2">
							<IoIosClose
								className="h-8 w-8 text-foreground"
								onClick={() => setOpen(!open)}
							/>
						</div>
					</div>
					<div className="flex flex-col items-start justify-start gap-[14px] px-8">
						{navItems.map((navItem: any, idx: number) => (
							<>
								{navItem.children && navItem.children.length > 0 ? (
									<>
										{navItem.children.map(
											(childNavItem: any, idx: number) => (
												<Link
													key={`link=${idx}`}
													href={childNavItem.link}
													onClick={() => setOpen(false)}
													className="relative max-w-[15rem] text-left text-2xl"
												>
													<span className="block text-foreground">
														{childNavItem.title}
													</span>
												</Link>
											)
										)}
									</>
								) : (
									<Link
										key={`link=${idx}`}
										href={navItem.link}
										onClick={() => setOpen(false)}
										className="relative"
									>
										<span className="block text-[26px] text-foreground">
											{navItem.title}
										</span>
									</Link>
								)}
							</>
						))}
					</div>
					<div className="flex flex-row w-full items-start gap-2.5  px-8 py-4 ">
						<Button>Book a demo</Button>
						<Button
							variant="simple"
							as={Link}
							href="/register"
							onClick={() => {
								setOpen(false);
							}}
						>
							Register
						</Button>
						{/* <ModeToggle /> */}
					</div>
				</div>
			)}
		</div>
	);
};

type NavBarItemProps = {
	href: string;
	children: ReactNode;
	active?: boolean;
	className?: string;
	target?: "_blank";
};

export function NavBarItem({
	children,
	href,
	active,
	target,
	className,
	toggleTheme,
}: NavBarItemProps) {
	const pathname = usePathname();

	return (
		<Link
			href={href}
			onClick={toggleTheme}
			className={cn(
				"border-y-2 border-y-red-500 w-fit",
				"flex items-center pointer-events-auto h-fit w-fit justify-center  text-sm leading-[110%] px-4 py-2 text-foreground  hover:bg-background hover:text-foreground/80 dark:text-foreground hover:shadow-[0px_1px_0px_0px_#FFFFFF20_inset] transition duration-200",
				(active || pathname?.includes(href)) &&
					"bg-transparent dark:text-foreground",
				className
			)}
			target={target}
		>
			{children}
		</Link>
	);
}

export default ResizeNavBar;

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

"use client";

import React, { useEffect, useRef } from "react";

import ThemeToggle from "@/components/ui/navbar-components/theme-toggle";
import SVG from "react-inlinesvg";

import { ThemeToggleButton } from "./theme_changer/ThemeToggleButton";

const MouseFollowingEyes: React.FC = () => {
	const eye1Ref = useRef<HTMLDivElement>(null);
	const eye2Ref = useRef<HTMLDivElement>(null);
	const mousePos = useRef({ x: 0, y: 0 });

	useEffect(() => {
		const handleMouseMove = (e: MouseEvent) => {
			mousePos.current = { x: e.clientX, y: e.clientY };
		};

		window.addEventListener("mousemove", handleMouseMove);

		return () => window.removeEventListener("mousemove", handleMouseMove);
	}, []);

	return (
		<div className="flex justify-center items-center">
			<div className="flex space-x-2">
				<div className="group">
					<div className="group-hover:block hidden">
						<ThemeToggleButton
							showLabel
							variant="gif"
							url="https://media.giphy.com/media/KBbr4hHl9DSahKvInO/giphy.gif?cid=790b76112m5eeeydoe7et0cr3j3ekb1erunxozyshuhxx2vl&ep=v1_stickers_search&rid=giphy.gif&ct=s"
						/>
					</div>
					<div className="group-hover:hidden block">
						<Eye
							selfRef={eye1Ref}
							otherRef={eye2Ref}
							mousePos={mousePos}
						/>
					</div>
				</div>
				<div className="group">
					<SVG
						src={"/dbsbottom.svg"}
						title={"half of our logo"}
						height={80}
						width={233}
						className="stroke-white group-hover:block hidden"
						role="img"
						aria-label={"half of our logo"}
						loader={<span>Loading...</span>}
					/>
					<div className="group-hover:hidden block">
						<Eye
							selfRef={eye2Ref}
							otherRef={eye1Ref}
							mousePos={mousePos}
						/>
					</div>
				</div>
			</div>
		</div>
	);
};

interface EyeProps {
	selfRef: React.RefObject<HTMLDivElement>;
	otherRef: React.RefObject<HTMLDivElement>;
	mousePos: React.MutableRefObject<{ x: number; y: number }>;
}

const Eye: React.FC<EyeProps> = ({
	selfRef,
	otherRef,
	mousePos,
	showWhat,
	setShowWhat,
}) => {
	const pupilRef = useRef<HTMLDivElement>(null);
	const center = useRef({ x: 0, y: 0 });

	const updateCenter = () => {
		if (!selfRef.current) return;
		const rect = selfRef.current.getBoundingClientRect();
		center.current = {
			x: rect.left + rect.width / 2,
			y: rect.top + rect.height / 2,
		};
	};

	useEffect(() => {
		updateCenter();
		window.addEventListener("resize", updateCenter);

		let frameId: number;

		const animate = () => {
			const { x, y } = mousePos.current;

			const isInside = (ref: React.RefObject<HTMLDivElement>) => {
				const rect = ref.current?.getBoundingClientRect();
				if (!rect) return false;
				return (
					x >= rect.left &&
					x <= rect.right &&
					y >= rect.top &&
					y <= rect.bottom
				);
			};

			if (!(isInside(selfRef) || isInside(otherRef))) {
				const dx = x - center.current.x;
				const dy = y - center.current.y;
				const angle = Math.atan2(dy, dx);

				const maxMove = 10;
				const pupilX = Math.cos(angle) * maxMove;
				const pupilY = Math.sin(angle) * maxMove;

				if (pupilRef.current) {
					pupilRef.current.style.transform = `translate(${pupilX}px, ${pupilY}px)`;
				}
			}

			frameId = requestAnimationFrame(animate);
		};

		frameId = requestAnimationFrame(animate);

		return () => {
			cancelAnimationFrame(frameId);
			window.removeEventListener("resize", updateCenter);
		};
	}, [selfRef, otherRef, mousePos]);

	return (
		<div
			ref={selfRef}
			className="relative bg-white border-4 border-black rounded-full h-12 w-12 flex items-center justify-center"
		>
			<div ref={pupilRef} className="absolute bg-black rounded-full h-4 w-4">
				<div className="w-1 h-1 bg-white rounded-full absolute bottom-1 right-1"></div>
			</div>
		</div>
	);
};

export { MouseFollowingEyes };

"use client";

import { Toggle } from "@/components/ui/toggle";
import { MoonIcon, SunIcon } from "lucide-react";
import { useTheme } from "next-themes";

export default function ThemeToggle() {
	const { theme, setTheme } = useTheme();

	return (
		<div>
			<Toggle
				variant="outline"
				className="group data-[state=on]:hover:bg-muted text-muted-foreground data-[state=on]:text-muted-foreground data-[state=on]:hover:text-foreground size-8 rounded-full border-none shadow-none data-[state=on]:bg-transparent"
				pressed={theme === "dark"}
				onPressedChange={() =>
					setTheme((prev) => (prev === "dark" ? "light" : "dark"))
				}
				aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} mode`}
			>
				{/* Note: After dark mode implementation, rely on dark: prefix rather than group-data-[state=on]: */}
				<MoonIcon
					size={16}
					className="shrink-0 scale-0 opacity-0 transition-all group-data-[state=on]:scale-100 group-data-[state=on]:opacity-100"
					aria-hidden="true"
				/>
				<SunIcon
					size={16}
					className="absolute shrink-0 scale-100 opacity-100 transition-all group-data-[state=on]:scale-0 group-data-[state=on]:opacity-0"
					aria-hidden="true"
				/>
			</Toggle>
		</div>
	);
}

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import * as TogglePrimitive from "@radix-ui/react-toggle";
import { cva, type VariantProps } from "class-variance-authority";

const toggleVariants = cva(
	"inline-flex items-center justify-center rounded-md text-sm font-medium ring-offset-background transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground",
	{
		variants: {
			variant: {
				default: "bg-transparent",
				outline:
					"border border-input bg-transparent hover:bg-accent hover:text-accent-foreground",
			},
			size: {
				default: "h-10 px-3",
				sm: "h-9 px-2.5",
				lg: "h-11 px-5",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

const Toggle = React.forwardRef<
	React.ElementRef<typeof TogglePrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof TogglePrimitive.Root> &
		VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
	<TogglePrimitive.Root
		ref={ref}
		className={cn(toggleVariants({ variant, size, className }))}
		{...props}
	/>
));

Toggle.displayName = TogglePrimitive.Root.displayName;

export { Toggle, toggleVariants };

